class ModelUtils:
    _MODELS = {}
    def register_model(cls=None, *, name=None):
        def _register(cls):
            if name is None:
                local_name = cls.__name__
            else:
                local_name = name
            ModelUtils._MODELS[local_name] = cls
            return cls
        if cls is None:
            return _register
        else:
            return _register(cls)
    def get_sigmas(config):
        return np.exp(np.linspace(np.log(config.model.sigma_max), np.log(config.model.sigma_min), config.model.num_scales))
    def create_model(config, local_rank=None):
        model_name = config.model.name
        score_model = ModelUtils._MODELS[model_name](config)
        if local_rank is None:
            score_model = score_model.cuda()
        else:
            score_model = score_model.to(f"{config.device}:{local_rank}")
            score_model = torch.nn.parallel.DistributedDataParallel(
                score_model, find_unused_parameters=True, device_ids=[local_rank])
        return score_model
    def get_score_fn(sde, model, train=False, continuous=False, cond=False):
        def model_fn(x, labels, l=None):
            if not train:
                model.eval()
                return model(x, labels, l)
            else:
                model.train()
                return model(x, labels, l)
        if isinstance(sde, SDE_Lib_VPSDE) or isinstance(sde, SDE_Lib_subVPSDE):
            if cond:
                def score_fn(x, t, l):
                    if continuous:
                        labels = t * 999
                        score = model_fn(x, labels, l)
                        std = sde.marginal_prob(torch.zeros_like(x), t)[1]
                    else:
                        labels = t * (sde.N - 1)
                        labels = torch.round(labels).long()
                        score = model_fn(x, labels, l)
                        std = sde.sqrt_1m_alphas_cumprod.to(labels.device)[labels.long()]
                    score = -score / std[:, None, None, None]
                    return score
            else:
                def score_fn(x, t):
                    if continuous:
                        labels = t * 999
                        score = model_fn(x, labels)
                        std = sde.marginal_prob(torch.zeros_like(x), t)[1]
                    else:
                        labels = t * (sde.N - 1)
                        score = model_fn(x, labels)
                        std = sde.sqrt_1m_alphas_cumprod.to(labels.device)[labels.long()]
                    score = -score / std[:, None, None, None]
                    return score
        else:
            raise NotImplementedError(
                f"SDE class {sde.__class__.__name__} not yet supported.")
        return score_fn

