class SDE_Lib_VPSDE:
    def __init__(self, beta_min, beta_max, N):
        self.beta_0 = beta_min
        self.beta_1 = beta_max
        self.N = N
    def transform_prob(self, t):
        log_mean_coeff = -0.25 * t ** 2 * (self.beta_1 - self.beta_0) - 0.5 * t * self.beta_0
        s = torch.exp(log_mean_coeff)
        sigma = torch.sqrt(1. - torch.exp(2. * log_mean_coeff))
        return s, sigma/s
    def marginal_prob(self, x, t):
        log_mean_coeff = -0.25 * t ** 2 * (self.beta_1 - self.beta_0) - 0.5 * t * self.beta_0
        mean = torch.exp(log_mean_coeff[:, None, None, None]) * x
        std = torch.sqrt(1. - torch.exp(2. * log_mean_coeff))
        return mean, std

class SDE_Lib_subVPSDE(SDE_Lib_VPSDE):
    pass

class SDE_Lib_VESDE(SDE_Lib_VPSDE):
    def __init__(self, sigma_min, sigma_max, N):
        self.sigma_min = sigma_min
        self.sigma_max = sigma_max
        self.N = N
    def transform_prob(self, t):
        s = torch.tensor([1])
        sigma = torch.tensor([self.sigma_min * (self.sigma_max / self.sigma_min) ** t])
        return s, sigma/s
    def marginal_prob(self, x, t):
        std = self.sigma_min * (self.sigma_max / self.sigma_min) ** t
        mean = x
        return mean, std

sde_lib = {'VPSDE': SDE_Lib_VPSDE, 'subVPSDE': SDE_Lib_subVPSDE, 'VESDE': SDE_Lib_VESDE}

