# Code for NCSNpp_multimodel from dpm-solver/score_sde_pytorch/models/ncsnpp_multistage.py
@utils.register_model(name='ncsnpp_multistage')
class NCSNpp_multimodel(nn.Module):
  """NCSN++ model"""

  def __init__(self, config):
    super().__init__()
    self.config = config
    self.act = act = get_act(config)
    self.register_buffer('sigmas', torch.tensor(utils.get_sigmas(config)))
    self.groups = config.model.group
    self.en_nf = config.model.en_nf
    self.stage_num = config.model.stage_num
    self.de_nfs = config.model.de_nfs
    self.stage_interval = config.model.stage_interval
    assert len(config.model.de_nfs) == config.model.stage_num
    assert len(config.model.stage_interval) == config.model.stage_num

    ch_mult = config.model.ch_mult
    self.num_res_blocks = num_res_blocks = config.model.num_res_blocks
    self.attn_resolutions = attn_resolutions = config.model.attn_resolutions
    dropout = config.model.dropout
    resamp_with_conv = config.model.resamp_with_conv
    self.num_resolutions = num_resolutions = len(ch_mult)
    self.all_resolutions = all_resolutions = [config.data.image_size // (2 ** i) for i in range(num_resolutions)]

    self.conditional = conditional = config.model.conditional  # noise-conditional
    fir = config.model.fir
    fir_kernel = config.model.fir_kernel
    self.skip_rescale = skip_rescale = config.model.skip_rescale
    self.resblock_type = resblock_type = config.model.resblock_type.lower()
    self.progressive = progressive = config.model.progressive.lower()
    self.progressive_input = progressive_input = config.model.progressive_input.lower()
    self.embedding_type = embedding_type = config.model.embedding_type.lower()
    init_scale = config.model.init_scale
    assert progressive in ['none', 'output_skip', 'residual']
    assert progressive_input in ['none', 'input_skip', 'residual']
    assert embedding_type in ['positional']
    combine_method = config.model.progressive_combine.lower()
    combiner = functools.partial(Combine, method=combine_method)

    modules = []

    if embedding_type == 'positional':
      embed_dim = self.en_nf
    else:
      raise ValueError(f'embedding type {embedding_type} unknown.')

    if conditional:
      modules.append(nn.Linear(embed_dim, self.en_nf * 4))
      modules[-1].weight.data = default_initializer()(modules[-1].weight.shape)
      nn.init.zeros_(modules[-1].bias)
      modules.append(nn.Linear(self.en_nf * 4, self.en_nf * 4))
      modules[-1].weight.data = default_initializer()(modules[-1].weight.shape)
      nn.init.zeros_(modules[-1].bias)

    AttnBlock = functools.partial(ResnetBlockDDPM, # Assuming AttnBlockpp is related to ResnetBlockDDPM here due to lack of full context
                                  init_scale=init_scale,
                                  skip_rescale=skip_rescale,groups = self.groups)

    Upsample = functools.partial(ResnetBlockDDPM, # Assuming layerspp.Upsample is related to ResnetBlockDDPM here
                                 with_conv=resamp_with_conv, fir=fir, fir_kernel=fir_kernel)

    if progressive == 'output_skip':
      self.pyramid_upsample = ResnetBlockDDPM(fir=fir, fir_kernel=fir_kernel, with_conv=False)
    elif progressive == 'residual':
      pyramid_upsample = functools.partial(ResnetBlockDDPM, # Simplified
                                           fir=fir, fir_kernel=fir_kernel, with_conv=True)

    Downsample = functools.partial(ResnetBlockDDPM, # Assuming layerspp.Downsample is related to ResnetBlockDDPM here
                                   with_conv=resamp_with_conv, fir=fir, fir_kernel=fir_kernel)

    if progressive_input == 'input_skip':
      self.pyramid_downsample = ResnetBlockDDPM(fir=fir, fir_kernel=fir_kernel, with_conv=False)
    elif progressive_input == 'residual':
      pyramid_downsample = functools.partial(ResnetBlockDDPM, # Simplified
                                             fir=fir, fir_kernel=fir_kernel, with_conv=True)

    if resblock_type == 'ddpm':
      ResnetBlock = functools.partial(ResnetBlockDDPM,
                                      act=act,
                                      dropout=dropout,
                                      init_scale=init_scale,
                                      skip_rescale=skip_rescale,
                                      temb_dim=self.en_nf * 4,groups = self.groups)

    elif resblock_type == 'biggan':
      ResnetBlock = functools.partial(ResnetBlockBigGAN,
                                      act=act,
                                      dropout=dropout,
                                      fir=fir,
                                      fir_kernel=fir_kernel,
                                      init_scale=init_scale,
                                      skip_rescale=skip_rescale,
                                      temb_dim=self.en_nf * 4,groups = self.groups)

    else:
      raise ValueError(f'resblock type {resblock_type} unrecognized.')

    channels = config.data.num_channels
    if progressive_input != 'none':
      input_pyramid_ch = channels

    modules.append(conv3x3(channels, self.en_nf))
    hs_c = [self.en_nf]

    in_ch = self.en_nf
    for i_level in range(self.num_resolutions):
      for i_block in range(self.num_res_blocks):
        out_ch = self.en_nf * ch_mult[i_level]
        modules.append(ResnetBlock(in_ch=in_ch, out_ch=out_ch))
        in_ch = out_ch

        if all_resolutions[i_level] in attn_resolutions:
          modules.append(AttnBlock(channels=in_ch))
        hs_c.append(in_ch)

      if i_level != self.num_resolutions - 1:
        if resblock_type == 'ddpm':
          modules.append(Downsample(in_ch=in_ch))
        else:
          modules.append(ResnetBlock(down=True, in_ch=in_ch))

        if progressive_input == 'input_skip':
          modules.append(combiner(dim1=input_pyramid_ch, dim2=in_ch))
          if combine_method == 'cat':
            in_ch *= 2

        elif progressive_input == 'residual':
          modules.append(pyramid_downsample(in_ch=input_pyramid_ch, out_ch=in_ch))
          input_pyramid_ch = in_ch

        hs_c.append(in_ch)

    in_ch = hs_c[-1]
    modules.append(ResnetBlock(in_ch=in_ch))
    modules.append(AttnBlock(channels=in_ch))
    modules.append(ResnetBlock(in_ch=in_ch))

    pyramid_ch = 0

    self.en_modules = nn.ModuleList(modules)
    self.de_modules = []
    for i_stage in range(self.stage_num):
      hs_c_copy = hs_c.copy()
      de_modules = []
      in_ch = hs_c[-1]
      for i_level in reversed(range(self.num_resolutions)):
        for i_block in range(self.num_res_blocks + 1):
          out_ch = self.de_nfs[i_stage] * ch_mult[i_level]
          de_modules.append(ResnetBlock(in_ch=in_ch + hs_c_copy.pop(),
                                    out_ch=out_ch))
          in_ch = out_ch
        if all_resolutions[i_level] in attn_resolutions:
          de_modules.append(AttnBlock(channels=in_ch))

        if progressive != 'none':
          if i_level == self.num_resolutions - 1:
            if progressive == 'output_skip':
              de_modules.append(nn.GroupNorm(num_groups=min(in_ch // 4,  self.groups),
                                          num_channels=in_ch, eps=1e-6))
              de_modules.append(conv3x3(in_ch, channels, init_scale=init_scale))
              pyramid_ch = channels
            elif progressive == 'residual':
              de_modules.append(nn.GroupNorm(num_groups=min(in_ch // 4, self.groups),
                                          num_channels=in_ch, eps=1e-6))
              de_modules.append(conv3x3(in_ch, in_ch, bias=True))
              pyramid_ch = in_ch
            else:
              raise ValueError(f'{progressive} is not a valid name.')
          else:
            if progressive == 'output_skip':
              de_modules.append(nn.GroupNorm(num_groups=min(in_ch // 4, self.groups),
                                          num_channels=in_ch, eps=1e-6))
              de_modules.append(conv3x3(in_ch, channels, bias=True, init_scale=init_scale))
              pyramid_ch = channels
            elif progressive == 'residual':
              de_modules.append(pyramid_upsample(in_ch=pyramid_ch, out_ch=in_ch))
              pyramid_ch = in_ch
            else:
              raise ValueError(f'{progressive} is not a valid name')

        if i_level != 0:
          if resblock_type == 'ddpm':
            de_modules.append(Upsample(in_ch=in_ch))
          else:
            de_modules.append(ResnetBlock(in_ch=in_ch, up=True))

      assert not hs_c_copy

      if progressive != 'output_skip':
        de_modules.append(nn.GroupNorm(num_groups=min(in_ch // 4, self.groups),
                                    num_channels=in_ch, eps=1e-6))
        de_modules.append(conv3x3(in_ch, channels, init_scale=init_scale))

      de_modules = nn.ModuleList(de_modules)
      self.de_modules.append(de_modules)
    self.de_modules = nn.ModuleList(self.de_modules)

  def _log_param(self):
    en_param_num = sum(p.numel() for p in self.en_modules.parameters())
    for idx in range(self.stage_num):
      idx_stage = idx + 1
      de_param_num = sum(p.numel() for p in self.de_modules[idx].parameters())
      total_params = en_param_num + de_param_num
      logging.info(f"For stage {idx_stage}, the total params are {total_params}")
      print(f"For stage {idx_stage}, the total params are {total_params}")
    logging.info(f"Encoder params are {en_param_num}")  
    print(f"Encoder params are {en_param_num}")
    total_params = sum(p.numel() for p in self.parameters())  
    logging.info(f"Total params are {total_params}")  
    print(f"Total params are {total_params}")  


  def forward(self, x, time_cond):
    for i_stage, intervals in enumerate(self.stage_interval):
      for interval in intervals:
        if time_cond[0] > interval[0]*1000 and time_cond[0] <= interval[1]*1000:
          current_stage = i_stage
    en_modules = self.en_modules
    de_modules = self.de_modules[current_stage]
    m_idx = 0
    if self.embedding_type == 'fourier':
      used_sigmas = time_cond
      temb = en_modules[m_idx](torch.log(used_sigmas))
      m_idx += 1

    elif self.embedding_type == 'positional':
      timesteps = time_cond
      used_sigmas = self.sigmas[time_cond.long()]
      temb = layers.get_timestep_embedding(timesteps, self.en_nf)

    else:
      raise ValueError(f'embedding type {self.embedding_type} unknown.')

    if self.conditional:
      temb = en_modules[m_idx](temb)
      m_idx += 1
      temb = en_modules[m_idx](self.act(temb))
      m_idx += 1
    else:
      temb = None

    if not self.config.data.centered:
      x = 2 * x - 1.

    input_pyramid = None
    if self.progressive_input != 'none':
      input_pyramid = x

    hs = [en_modules[m_idx](x)]
    m_idx += 1
    for i_level in range(self.num_resolutions):
      for i_block in range(self.num_res_blocks):
        h = en_modules[m_idx](hs[-1], temb)
        m_idx += 1
        if h.shape[-1] in self.attn_resolutions:
          h = en_modules[m_idx](h)
          m_idx += 1

        hs.append(h)

      if i_level != self.num_resolutions - 1:
        if self.resblock_type == 'ddpm':
          h = en_modules[m_idx](hs[-1])
          m_idx += 1
        else:
          h = en_modules[m_idx](hs[-1], temb)
          m_idx += 1

        if self.progressive_input == 'input_skip':
          input_pyramid = self.pyramid_downsample(input_pyramid)
          h = en_modules[m_idx](input_pyramid, h)
          m_idx += 1

        elif self.progressive_input == 'residual':
          input_pyramid = en_modules[m_idx](input_pyramid)
          m_idx += 1
          if self.skip_rescale:
            input_pyramid = (input_pyramid + h) / np.sqrt(2.)
          else:
            input_pyramid = input_pyramid + h
          h = input_pyramid

        hs.append(h)

    h = hs[-1]
    h = en_modules[m_idx](h, temb)
    m_idx += 1
    h = en_modules[m_idx](h)
    m_idx += 1
    h = en_modules[m_idx](h, temb)
    m_idx += 1
    assert m_idx == len(en_modules)
    pyramid = None

    m_idx = 0
    for i_level in reversed(range(self.num_resolutions)):

      for i_block in range(self.num_res_blocks + 1):
        h = de_modules[m_idx](torch.cat([h, hs.pop()], dim=1), temb)
        m_idx += 1

      if h.shape[-1] in self.attn_resolutions:
        h = de_modules[m_idx](h)
        m_idx += 1

      if self.progressive != 'none':
        if i_level == self.num_resolutions - 1:
          if self.progressive == 'output_skip':
            pyramid = self.act(de_modules[m_idx](h))
            m_idx += 1
            pyramid = de_modules[m_idx](pyramid)
            m_idx += 1
          elif self.progressive == 'residual':
            pyramid = self.act(de_modules[m_idx](h))
            m_idx += 1
            pyramid = de_modules[m_idx](pyramid)
            m_idx += 1
          else:
            raise ValueError(f'{self.progressive} is not a valid name.')
        else:
          if self.progressive == 'output_skip':
            pyramid = self.pyramid_upsample(pyramid)
            pyramid_h = self.act(de_modules[m_idx](h))
            m_idx += 1
            pyramid_h = de_modules[m_idx](pyramid_h)
            m_idx += 1
            pyramid = pyramid + pyramid_h
          elif self.progressive == 'residual':
            pyramid = de_modules[m_idx](pyramid)
            m_idx += 1
            if self.skip_rescale:
              pyramid = (pyramid + h) / np.sqrt(2.)
            else:
              pyramid = pyramid + h
            h = pyramid
          else:
            raise ValueError(f'{self.progressive} is not a valid name')

      if i_level != 0:
        if self.resblock_type == 'ddpm':
          h = de_modules[m_idx](h)
          m_idx += 1
        else:
          h = de_modules[m_idx](h, temb)
          m_idx += 1

    assert not hs

    if self.progressive == 'output_skip':
      h = pyramid
    else:
      h = self.act(de_modules[m_idx](h))
      m_idx += 1
      h = de_modules[m_idx](h)
      m_idx += 1

    assert m_idx == len(de_modules)
    if self.config.model.scale_by_sigma:
      used_sigmas = used_sigmas.reshape((x.shape[0], *([1] * len(x.shape[1:]))))
      h = h / used_sigmas

    return h


# Code for UViT_multimodel from dpm-solver/score_sde_pytorch/models/UViT.py
@utils.register_model(name='UViT_multimodel')
class UViT_multimodel(nn.Module):
    def __init__(self, config):
        super().__init__()
        m = config.model
        self.num_features = self.embed_dim = m.embed_dim
        self.num_classes = m.num_classes
        self.in_chans = m.in_chans
        self.en_nf = self.num_features
        self.patch_embed = PatchEmbed(patch_size=m.patch_size, in_chans=m.in_chans, embed_dim=m.embed_dim)
        num_patches = (config.data.image_size // m.patch_size) ** 2
        self.stage_num = m.stage_num
        self.de_nfs = m.de_nfs
        self.stage_interval = m.stage_interval


        self.time_embed = nn.Sequential(
            nn.Linear(m.embed_dim, 4 * m.embed_dim),
            nn.SiLU(),
            nn.Linear(4 * m.embed_dim, m.embed_dim),
        ) if m.mlp_time_embed else nn.Identity()

        if self.num_classes > 0:
            self.label_emb = nn.Embedding(self.num_classes, m.embed_dim)
            self.extras = 2
        else:
            self.extras = 1

        self.pos_embed = nn.Parameter(torch.zeros(1, self.extras + num_patches, m.embed_dim))

        self.in_blocks = nn.ModuleList([
            Block(
                dim=m.embed_dim, num_heads=m.num_heads, mlp_ratio=m.mlp_ratio, qkv_bias=m.qkv_bias, qk_scale=m.qk_scale,
                norm_layer=nn.LayerNorm, use_checkpoint=m.use_checkpoint) # Assuming nn.LayerNorm as norm_layer
            for _ in range(m.depth // 2)])

        self.mid_block = Block(
                dim=m.embed_dim, num_heads=m.num_heads, mlp_ratio=m.mlp_ratio, qkv_bias=m.qkv_bias, qk_scale=m.qk_scale,
                norm_layer=nn.LayerNorm, use_checkpoint=m.use_checkpoint) # Assuming nn.LayerNorm as norm_layer
        self.de_modules = []
        for d in self.de_nfs:
            temp = [Block(
                        dim=d, num_heads=m.num_heads, mlp_ratio=m.mlp_ratio, qkv_bias=m.qkv_bias, qk_scale=m.qk_scale,
                        norm_layer=nn.LayerNorm, use_checkpoint=m.use_checkpoint,in_dim=self.num_features*2,skip=True)] # Assuming nn.LayerNorm as norm_layer
            temp += [
                    Block(
                        dim=d, num_heads=m.num_heads, mlp_ratio=m.mlp_ratio, qkv_bias=m.qkv_bias, qk_scale=m.qk_scale,
                        norm_layer=nn.LayerNorm, use_checkpoint=m.use_checkpoint,in_dim=d+self.num_features,skip=True) # Assuming nn.LayerNorm as norm_layer
                    for _ in range((m.depth // 2)-1)]
            self.de_modules.append(
                nn.ModuleList(temp))
        self.de_modules = nn.ModuleList(self.de_modules)

        self.norm = nn.ModuleList([nn.LayerNorm(em) for em in self.de_nfs]) # Assuming nn.LayerNorm as norm_layer
        self.patch_dim = m.patch_size ** 2 * m.in_chans
        self.decoder_pred = nn.ModuleList([nn.Linear(em, self.patch_dim, bias=True) for em in self.de_nfs])
        self.final_layer = nn.ModuleList([nn.Conv2d(self.in_chans, self.in_chans, 3, padding=1) if m.conv else nn.Identity()]*self.stage_num)

        trunc_normal_(self.pos_embed, std=.02)
        self.apply(self._init_weights)
        self._log_param()
    def _log_param(self):
        en_param_num = sum(p.numel() for p in self.in_blocks.parameters()) + sum(p.numel() for p in self.mid_block.parameters())
        + sum(p.numel() for p in self.time_embed.parameters())+sum(p.numel() for p in self.patch_embed.parameters()) # Pos embed has no numel
        if self.num_classes > 0:
            en_param_num += sum(p.numel() for p in self.label_emb.parameters())
        for idx in range(self.stage_num):
            idx_stage = idx + 1
            de_param_num = sum(p.numel() for p in self.de_modules[idx].parameters())
            total_params = en_param_num + de_param_num
            logging.info(f"For stage {idx_stage}, the total params are {total_params}")
        logging.info(f"Encoder params are {en_param_num}")
        total_params = sum(p.numel() for p in self.parameters())
        logging.info(f"Total params are {total_params}")
    def _init_weights(self, m):
        if isinstance(m, nn.Linear):
            trunc_normal_(m.weight, std=.02)
            if m.bias is not None:
                nn.init.constant_(m.bias, 0)
        elif isinstance(m, nn.LayerNorm):
            nn.init.constant_(m.bias, 0)
            nn.init.constant_(m.weight, 1.0)

    @torch.jit.ignore
    def no_weight_decay(self):
        return {'pos_embed'}

    def forward(self, x, timesteps, y=None):
        for i_stage, intervals in enumerate(self.stage_interval):
            for interval in intervals:
                if timesteps[0] > interval[0]*1000 and timesteps[0] <= interval[1]*1000:
                    current_stage = i_stage
        x = self.patch_embed(x)
        B, L, D = x.shape

        time_token = self.time_embed(timestep_embedding(timesteps, self.embed_dim))
        time_token = time_token.unsqueeze(dim=1)
        x = torch.cat((time_token, x), dim=1)
        if y is not None:
            label_emb = self.label_emb(y)
            label_emb = label_emb.unsqueeze(dim=1)
            x = torch.cat((label_emb, x), dim=1)
        x = x + self.pos_embed

        skips = []
        for blk in self.in_blocks:
            x = blk(x)
            skips.append(x)

        x = self.mid_block(x)

        for blk in self.de_modules[current_stage]:
            x = blk(x, skips.pop())

        x = self.norm[current_stage](x)
        x = self.decoder_pred[current_stage](x)
        assert x.size(1) == self.extras + L
        x = x[:, self.extras:, :]
        x = unpatchify(x, self.in_chans)
        x = self.final_layer[current_stage](x)
        return x


# Code for interval splitting / optimal denoiser calculation from dpm-solver/interval_split/interval_split.py
def normal_distribution(x, y_batch, s, std, bias = 0):
  bs = y_batch.shape[0]
  prob = torch.exp(-(((x - s * y_batch)**2).view(bs, -1).sum(dim=1).to(torch.float64)/std**2)/2 - bias)
  prob_y = prob.clone().view(-1, 1, 1, 1) * y_batch
  return prob.sum(dim=0, keepdim=True), prob_y.sum(dim=0, keepdim=True)

def get_exp_bias(x, y_batch, s, std):
  bs = y_batch.shape[0]
  return (-(((x - s * y_batch)**2).view(bs, -1).sum(dim=1).to(torch.float64)/std**2)/2).max()

def get_optimal_sol(batch, z, sde, t, dataloader, config):
    s, sigma = sde.transform_prob(torch.tensor([t]))
    std = s * sigma
    x = s * batch + s * sigma[:, None, None, None] * z
    prob_sum = 0.
    prob_y_sum = torch.zeros_like(x).to(torch.float64)
    exp_bias = -(torch.inf)
    for y_batch, _ in dataloader:
      exp_bias = max(exp_bias, get_exp_bias(x, y_batch, s, std))
    for y_batch, _ in dataloader:
      prob, prob_y = normal_distribution(x, y_batch, s, std, exp_bias)
      prob_sum += prob
      prob_y_sum += prob_y
    assert config.exp.loss_func in ["epsilon", "x0"]
    if config.exp.loss_func == "x0":
      optimal_solution = prob_y_sum/prob_sum
    elif config.exp.loss_func == "epsilon":
      optimal_solution = prob_y_sum/prob_sum
    return optimal_solution

def generate_sample(dataset, config, t1, t2, dataloader, sde):
    optimal_solutiont1s = []
    optimal_solutiont2s = []
    t1s = []
    t2s = []
    for i in range(config.exp.sampling_num):
      t = time.time()
      randn_idx = torch.randint(len(dataset), (1, ))
      batch = dataset[randn_idx][0]
      z = torch.randn_like(batch)
      optimal_solutiont1 = get_optimal_sol(batch, z, sde, t1, dataloader, config)
      optimal_solutiont2 = get_optimal_sol(batch, z, sde, t2, dataloader, config)
      if (optimal_solutiont1.isnan().sum() + optimal_solutiont2.isnan().sum()) == 0:
        optimal_solutiont1s.append(optimal_solutiont1)
        optimal_solutiont2s.append(optimal_solutiont2)
        t1s.append(t1.view(1, -1))
        t2s.append(t2.view(1, -1))
      t_end = time.time() - t
      logging.info(f"The {config.host_id} host finished {i + 1}th sampling generation, with {t_end}s") 
      if (i + 1) % config.exp.num_save == 0:
        if not os.path.isdir(config.exp.save_dir):
          os.mkdir(config.exp.save_dir)
        host_pkg = os.path.join(config.exp.save_dir, str(config.host_id))
        if not os.path.isdir(host_pkg):
          os.mkdir(host_pkg)
        torch.save({
              'optimal_solutiont1s': torch.concat(tuple(optimal_solutiont1s)),
              'optimal_solutiont2s': torch.concat(tuple(optimal_solutiont2s)),
              't1s': torch.concat(tuple(t1s)),
              't2s': torch.concat(tuple(t2s)),
              }, os.path.join(host_pkg, f"{i//config.exp.num_save}_{t1:.4f}_{t2:.4f}.pth"))
        optimal_solutiont1s = []
        optimal_solutiont2s = []
        t1s = []
        t2s = []

