# Code for interval clustering algorithm from dpm-solver/score_sde_pytorch/cluster.py
class interval_cluster:
    def __init__(self,timesteps,k):
        self.timesteps = timesteps
        self.k = k
        self.num = len(timesteps)
        self.mi = floor(self.num/(2*self.k))
        self.MI = ceil(3*self.num/(2*self.k))
    def calculate(self,time_cost):
        mi = self.mi
        MI = self.MI
        num = self.num
        k = self.k
        D = np.zeros((self.num,self.k))
        B = np.zeros_like(D,dtype=int)
        D[:,:] = np.inf
        D[:,0] = [time_cost(x) for x in [self.timesteps[:i] for i in range(1,self.num+1)]]
        for m in range(1,self.k):
            lower = 1+(m)*mi
            start = num-1 if m == self.k-1 else m
            for i in range(start,num):
                lb = max(lower,i+1-MI)
                ub = i+1-mi
                if ub < lb:
                    continue
                lcs = [time_cost(x) for x in [self.timesteps[t:i+1] for t in range(lb,ub+1)]]
                temp = D[lb-1:ub,m-1] + lcs
                minj = np.argmin(temp)
                D[i,m] = temp[minj]
                B[i,m] = minj+lb 
        lms = [B[num-1,k-1]]
        temp = list(range(k-1))
        temp.reverse()
        for m in temp:
            lms.append(B[lms[-1]-1,m])

        return lms,self.timesteps[lms]

# Code for gradient-based clustering from dpm-solver/score_sde_pytorch/gradient_cluster.py
def get_loss_fn(sde, train,reduce_mean=True, continuous=True, likelihood_weighting=True, eps=1e-5):
  reduce_op = torch.mean if reduce_mean else lambda *args, **kwargs: 0.5 * torch.sum(*args, **kwargs)
  def loss_fn(model,batch,timestep):
    score_fn = utils.get_score_fn(sde, model, train=train, continuous=continuous)
    t = torch.ones(batch.shape[0], device=batch.device)*timestep
    z = torch.randn_like(batch)
    mean, std = sde.marginal_prob(batch, t)
    perturbed_data = mean + std[:, None, None, None] * z
    score = score_fn(perturbed_data, t)
    if not likelihood_weighting:
      losses = torch.square(score * std[:, None, None, None] + z)
      losses = reduce_op(losses.reshape(losses.shape[0], -1), dim=-1)
    else:
      g2 = sde.sde(torch.zeros_like(batch), t)[1] ** 2
      losses = torch.square(score + z / std[:, None, None, None])
      losses = reduce_op(losses.reshape(losses.shape[0], -1), dim=-1) * g2
    loss = torch.mean(losses)
    return loss

  return loss_fn

